  var BUC = { d: 'Bucal = da bochecha. O nervo bucal (ramo do V3) inerva a gengiva e a mucosa VESTIBULAR dos molares inferiores: por isso o bloqueio do alveolar inferior não basta para extrair molar. Abertura bucal = abertura da boca.', fonte: FT };
